package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Set;

/**
 * Formats and reads an owner's customer code as {@code <REGION>-<HASH8>}, where
 * {@code REGION} is the region code derived from the owner's postcode (see
 * {@link org.springframework.samples.petclinic.model.CityRegion}) and {@code HASH8} is the
 * first 8 upper-case hex characters of {@code SHA-256(normalizedTelephone + lastName)}
 * (e.g. {@code NSW-1A2B3C4D}). The code is derived purely from the owner's own fields, so
 * the same owner always yields the same code without any sequence or coordination.
 */
public final class CustomerCode {

    /** Number of hex characters kept from the telephone-and-name hash. */
    private static final int HASH_LENGTH = 8;

    private CustomerCode() {
    }

    /**
     * The customer code for an owner in {@code region} whose normalized telephone and last
     * name are given.
     */
    public static String format(String region, String normalizedTelephone, String lastName) {
        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
        String last = lastName == null ? "" : lastName;
        return region + "-" + Hashes.upperHexPrefix(telephone + last, HASH_LENGTH);
    }

    /**
     * De-duplicates {@code code} against the codes already {@code taken}. Returns {@code code}
     * unchanged when it is free; otherwise appends {@code -<n>} with the smallest {@code n} of 2
     * or more that yields a code not in {@code taken} (e.g. {@code NSW-1A2B3C4D-2}).
     */
    public static String deduplicate(String code, Set<String> taken) {
        if (!taken.contains(code)) {
            return code;
        }
        for (int n = 2; ; n++) {
            String candidate = code + "-" + n;
            if (!taken.contains(candidate)) {
                return candidate;
            }
        }
    }

    /**
     * The {@code REGION} segment of a customer code — everything before the first {@code -}
     * separator, i.e. the region the code was minted in.
     */
    public static String region(String customerCode) {
        int separator = customerCode.indexOf('-');
        return separator < 0 ? customerCode : customerCode.substring(0, separator);
    }
}
==== AssignCustomerCode ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.CityRegion;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns a new owner's customer code before it is saved. The code is {@code <REGION>-<HASH8>}
 * (see {@link CustomerCode}): the region derived from the owner's postcode plus a hash of the
 * owner's normalized telephone and last name. Runs after the telephone has been normalized, so
 * {@link Owner#getTelephone()} already holds the canonical form the hash is taken over. Should
 * that code collide with an existing owner's, it is de-duplicated with a {@code -<n>} suffix.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String region = CityRegion.localityOf(owner.getPostcode(), owner.getCity());
        String code = CustomerCode.format(region, owner.getTelephone(), owner.getLastName());
        Set<String> taken = new HashSet<>();
        for (Owner existing : ownerRepository.findAllActive()) {
            if (existing.getCustomerCode() != null) {
                taken.add(existing.getCustomerCode());
            }
        }
        owner.setCustomerCode(CustomerCode.deduplicate(code, taken));
    }
}
==== CityRegion ====
package org.springframework.samples.petclinic.model;

import java.util.Map;

/**
 * The pinned region reference data used to derive an owner's locality. Knows both the
 * city-to-region table and each region's inclusive four-digit postcode range (NSW
 * 2000-2099, VIC 3000-3099, QLD 4000-4099).
 *
 * <p>Locality is derived by postcode first — {@link #localityOf(String, String)} looks up
 * the region whose range contains the postcode and only falls back to the city-to-region
 * table when the postcode is absent or in no known range. A city or postcode with no known
 * region resolves to {@link #UNKNOWN}.
 */
public final class CityRegion {

    /** Locality returned when neither postcode nor city resolves to a known region. */
    public static final String UNKNOWN = "UNKNOWN";

    private static final Map<String, String> CITY_TO_REGION = Map.of(
        "Sydney", "NSW",
        "Melbourne", "VIC",
        "Brisbane", "QLD");

    /** Region -> inclusive {low, high} four-digit postcode range. */
    private static final Map<String, int[]> REGION_RANGES = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /** Region -> IANA timezone name. */
    private static final Map<String, String> REGION_TIMEZONES = Map.of(
        "NSW", "Australia/Sydney",
        "VIC", "Australia/Melbourne",
        "QLD", "Australia/Brisbane");

    private CityRegion() {
    }

    /**
     * The canonical region for the given city, or {@link #UNKNOWN} when the city is not
     * in the table (including a {@code null} city).
     */
    public static String localityOf(String city) {
        return CITY_TO_REGION.getOrDefault(city, UNKNOWN);
    }

    /**
     * The canonical region, preferring the postcode: the region whose pinned range
     * contains {@code postcode}, falling back to the {@link #localityOf(String) city
     * table} when the postcode is absent or in no known range. This disambiguates cities
     * that share a name while still resolving known cities to the same region.
     */
    public static String localityOf(String postcode, String city) {
        String byPostcode = regionOfPostcode(postcode);
        return byPostcode != null ? byPostcode : localityOf(city);
    }

    /**
     * The region whose pinned range contains {@code postcode}, or {@code null} when the
     * postcode is {@code null}, not four digits, or in no known range.
     */
    public static String regionOfPostcode(String postcode) {
        if (postcode == null || !postcode.matches("\\d{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The IANA timezone name pinned to {@code region} (NSW -> Australia/Sydney, VIC ->
     * Australia/Melbourne, QLD -> Australia/Brisbane), or {@code null} when the region has
     * no pinned timezone (including {@link #UNKNOWN} and a {@code null} region).
     */
    public static String timezoneOf(String region) {
        return REGION_TIMEZONES.get(region);
    }

    /**
     * The inclusive {low, high} four-digit postcode range pinned to {@code region}, or
     * {@code null} when the region has no pinned range.
     */
    public static int[] rangeOf(String region) {
        int[] range = REGION_RANGES.get(region);
        return range == null ? null : range.clone();
    }
}

